#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; i++) {
        int pid_that;
        if (scanf("%d", &pid_that) != 1) return 1;
    }
    for (int i = 1; i <= n; i++) {
        printf("%d", i);
        if (i < n) printf(" ");
    }
    printf("\n");
    return 0;
}
